-- CA_0365: correct Matt Lehman's draft Season 3 gun-policy reasoning (Indiana House).
--
-- His reasoning said "His No on HB 1235 (lawsuit preemption)". The official House roll call 281 (2024, HB 1235 motion
-- to concur, 65-26), read 2026-11-04 through the MyIGA API, lists Lehman under Yea; LegiScan's record of the same vote
-- (64-27) has him Nay, and his store finding was copied from LegiScan. Found by the iga-votes.ts replay for PR #1308,
-- whose cross-check stopped on exactly this disagreement. HB 1235 is adjacent (no rung act), so his seat (rung 5, on
-- HB 1296 (2022)) does not change. Reasoning text only; value, sources and review rows unchanged.
-- Old text recorded below (the guard). Guarded on the exact old text: idempotent, and it refuses a row someone has
-- since edited. The store finding (act nay) is left as it is: it records what LegiScan printed.

BEGIN;

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM inform.politician_context
   WHERE season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND politician_id = '4f57bead-e464-4a26-bc14-49f9599f2086' AND reasoning IN ('Co-sponsor of IN HB 1296 (2022) and Yea on its House conference report, 2022-03-08. HB 1296 (2022) repeals the licence offence ("section 1 of this chapter (carrying a handgun without a license) (before its repeal)") and lists who "may not knowingly or intentionally carry a handgun"; it removes the permit to carry for adults, which is rung 5 ("Repeal laws that require a permit or registration for a gun, such as the permit to carry"). Its list of persons barred from permit-free carry is the condition that the permit-removal law sets on its own permit-free carry, part of the rung 5 act (annex closure C3), not a separate rung 3 act. Single-subject verdict (season 3, codebook 0.6), census gate none. His own words back it: words to the same effect (no readable page prints them) (caucus release, 2022-01-11). He also voted Yea on rung 4 acts (HB 1071 2017, HB 1084 2024, SB 43 2017); furthest act is 5. His No on HB 1235 (lawsuit preemption) is adjacent; no restriction-side rung act is ungated. A Yea on HB 1365 (2023, machine guns) is treated as no rung act (orchestrator note); if it were read as rung 2, this record would become two-sided and the row a BLANK adjacent-chairs.', 'Co-sponsor of IN HB 1296 (2022) and Yea on its House conference report, 2022-03-08. HB 1296 (2022) repeals the licence offence ("section 1 of this chapter (carrying a handgun without a license) (before its repeal)") and lists who "may not knowingly or intentionally carry a handgun"; it removes the permit to carry for adults, which is rung 5 ("Repeal laws that require a permit or registration for a gun, such as the permit to carry"). Its list of persons barred from permit-free carry is the condition that the permit-removal law sets on its own permit-free carry, part of the rung 5 act (annex closure C3), not a separate rung 3 act. Single-subject verdict (season 3, codebook 0.6), census gate none. His own words back it: words to the same effect (no readable page prints them) (caucus release, 2022-01-11). He also voted Yea on rung 4 acts (HB 1071 2017, HB 1084 2024, SB 43 2017); furthest act is 5. His Yea on HB 1235 (2024, lawsuit preemption) is adjacent; no restriction-side rung act is ungated. A Yea on HB 1365 (2023, machine guns) is treated as no rung act (orchestrator note); if it were read as rung 2, this record would become two-sided and the row a BLANK adjacent-chairs.');
  IF n <> 1 THEN RAISE EXCEPTION 'pre-flight: expected 1 row holding the old or new text, found %', n; END IF;
END $$;

UPDATE inform.politician_context SET reasoning = 'Co-sponsor of IN HB 1296 (2022) and Yea on its House conference report, 2022-03-08. HB 1296 (2022) repeals the licence offence ("section 1 of this chapter (carrying a handgun without a license) (before its repeal)") and lists who "may not knowingly or intentionally carry a handgun"; it removes the permit to carry for adults, which is rung 5 ("Repeal laws that require a permit or registration for a gun, such as the permit to carry"). Its list of persons barred from permit-free carry is the condition that the permit-removal law sets on its own permit-free carry, part of the rung 5 act (annex closure C3), not a separate rung 3 act. Single-subject verdict (season 3, codebook 0.6), census gate none. His own words back it: words to the same effect (no readable page prints them) (caucus release, 2022-01-11). He also voted Yea on rung 4 acts (HB 1071 2017, HB 1084 2024, SB 43 2017); furthest act is 5. His Yea on HB 1235 (2024, lawsuit preemption) is adjacent; no restriction-side rung act is ungated. A Yea on HB 1365 (2023, machine guns) is treated as no rung act (orchestrator note); if it were read as rung 2, this record would become two-sided and the row a BLANK adjacent-chairs.', updated_at = now()
 WHERE season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND politician_id = '4f57bead-e464-4a26-bc14-49f9599f2086' AND reasoning = 'Co-sponsor of IN HB 1296 (2022) and Yea on its House conference report, 2022-03-08. HB 1296 (2022) repeals the licence offence ("section 1 of this chapter (carrying a handgun without a license) (before its repeal)") and lists who "may not knowingly or intentionally carry a handgun"; it removes the permit to carry for adults, which is rung 5 ("Repeal laws that require a permit or registration for a gun, such as the permit to carry"). Its list of persons barred from permit-free carry is the condition that the permit-removal law sets on its own permit-free carry, part of the rung 5 act (annex closure C3), not a separate rung 3 act. Single-subject verdict (season 3, codebook 0.6), census gate none. His own words back it: words to the same effect (no readable page prints them) (caucus release, 2022-01-11). He also voted Yea on rung 4 acts (HB 1071 2017, HB 1084 2024, SB 43 2017); furthest act is 5. His No on HB 1235 (lawsuit preemption) is adjacent; no restriction-side rung act is ungated. A Yea on HB 1365 (2023, machine guns) is treated as no rung act (orchestrator note); if it were read as rung 2, this record would become two-sided and the row a BLANK adjacent-chairs.';

DO $$
DECLARE n int; v int;
BEGIN
  SELECT count(*) INTO n FROM inform.politician_context WHERE season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND politician_id = '4f57bead-e464-4a26-bc14-49f9599f2086' AND reasoning = 'Co-sponsor of IN HB 1296 (2022) and Yea on its House conference report, 2022-03-08. HB 1296 (2022) repeals the licence offence ("section 1 of this chapter (carrying a handgun without a license) (before its repeal)") and lists who "may not knowingly or intentionally carry a handgun"; it removes the permit to carry for adults, which is rung 5 ("Repeal laws that require a permit or registration for a gun, such as the permit to carry"). Its list of persons barred from permit-free carry is the condition that the permit-removal law sets on its own permit-free carry, part of the rung 5 act (annex closure C3), not a separate rung 3 act. Single-subject verdict (season 3, codebook 0.6), census gate none. His own words back it: words to the same effect (no readable page prints them) (caucus release, 2022-01-11). He also voted Yea on rung 4 acts (HB 1071 2017, HB 1084 2024, SB 43 2017); furthest act is 5. His Yea on HB 1235 (2024, lawsuit preemption) is adjacent; no restriction-side rung act is ungated. A Yea on HB 1365 (2023, machine guns) is treated as no rung act (orchestrator note); if it were read as rung 2, this record would become two-sided and the row a BLANK adjacent-chairs.';
  IF n <> 1 THEN RAISE EXCEPTION 'post-verify: expected 1 corrected row, found %', n; END IF;
  SELECT count(*) INTO v FROM inform.politician_answers WHERE season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND politician_id = '4f57bead-e464-4a26-bc14-49f9599f2086' AND value = 5;
  IF v <> 1 THEN RAISE EXCEPTION 'post-verify: seat moved (expected rung 5), found % matching', v; END IF;
END $$;

COMMIT;
